const $=id=>document.getElementById(id);
const places=[['광화문 · 종로','역사와 도심의 교차점',126.9788,37.5724,15.8,-22],['여의도','한강을 마주한 스카이라인',126.9258,37.5235,15.5,-30],['강남 · 테헤란로','대로를 따라 솟은 업무지구',127.0365,37.5008,15.6,28],['잠실','호수와 고층 건물 사이',127.1025,37.5130,15.6,-25],['성수','한강 북쪽의 도시 풍경',127.0445,37.5445,15.7,-25],['북한산','능선과 서울의 고도 차이',126.9780,37.6605,12.8,-20],['남산','도심 한가운데의 언덕',126.9918,37.5512,14.2,-30]];
let map,ready=false,terrainError=false;
// MapLibre requests tiles for the visible camera viewport, updates on pan/zoom,
// and manages an adaptive tile cache. Never preload nationwide data.
function message(s){$('status').textContent=s}
places.forEach((p,i)=>{const b=document.createElement('button');b.className='place'+(i===0?' active':'');b.innerHTML='<em>0'+(i+1)+'</em><span><strong>'+p[0]+'</strong><small>'+p[1]+'</small></span>';b.setAttribute('aria-pressed',i===0?'true':'false');b.onclick=()=>{if(!map)return;document.querySelectorAll('.place').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});b.classList.add('active');b.setAttribute('aria-pressed','true');$('location').textContent=p[0];map.flyTo({center:[p[2],p[3]],zoom:p[4],bearing:p[5],pitch:i>=5?65:+$('pitch').value,duration:1500})};$('places').append(b)});
async function start(){try{if(!window.maplibregl)throw Error('engine');await Cartography.load();const r=await fetch('https://tiles.openfreemap.org/styles/liberty');if(!r.ok)throw Error('style');const style=await r.json();const height=['coalesce',['get','render_height'],6];style.layers.forEach(l=>{if(l.id==='building-3d'){l.paint['fill-extrusion-color']=['interpolate',['linear'],height,0,'#d5ddd6',25,'#a9c8bc',70,'#7eb8aa',150,'#227f78',300,'#12544f'];l.paint['fill-extrusion-opacity']=0.97;l.paint['fill-extrusion-height']=height;l.paint['fill-extrusion-base']=['coalesce',['get','render_min_height'],0]}if(l.type==='symbol'&&l.layout?.['text-field'])l.layout['text-field']=['coalesce',['get','name:ko'],['get','name'],['get','name:en']]});
const dem={type:'raster-dem',tiles:['https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png'],tileSize:256,encoding:'terrarium',maxzoom:14,attribution:'Terrain: <a href="https://registry.opendata.aws/terrain-tiles/" target="_blank">Mapzen</a> · USGS SRTM / GMTED2010 · NOAA ETOPO1'};style.sources['terrain-dem']={...dem};style.sources['terrain-shade']={...dem};style.terrain={source:'terrain-dem',exaggeration:1};const shadeIndex=style.layers.findIndex(l=>l.type==='line'||l.id==='building');style.layers.splice(shadeIndex<0?1:shadeIndex,0,{id:'terrain-hillshade',type:'hillshade',source:'terrain-shade',paint:{'hillshade-exaggeration':0.35,'hillshade-shadow-color':'#526754','hillshade-highlight-color':'#fffceb','hillshade-accent-color':'#5e7060'}});
map=new maplibregl.Map({container:'map',style,center:[126.9788,37.5724],zoom:15.8,pitch:60,bearing:-22,maxPitch:70,minZoom:5,maxZoom:19,maxBounds:[[123,32],[133,40]],attributionControl:true});map.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');map.addControl(new maplibregl.ScaleControl({unit:'metric'}),'bottom-right');map.on('load',()=>{ready=true;message('');addLandcover(map);Cartography.mount(map);applyLayers()});map.on('error',e=>{if(e.sourceId==='terrain-dem'||e.sourceId==='terrain-shade'){terrainError=true;message('지형 고도 데이터를 불러오지 못했습니다. 연결을 확인하고 새로고침해 주세요.')}else message('지도 일부를 불러오지 못했습니다. 인터넷 연결을 확인하거나 페이지를 새로고침해 주세요.')});map.on('idle',()=>{if(ready&&!terrainError&&map.areTilesLoaded())message(map.getZoom()<14?'건물을 보려면 지도를 더 확대해 주세요.':'')});map.on('dragstart',()=>{$('location').textContent='대한민국 둘러보기';document.querySelectorAll('.place').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')})});map.on('move',()=>{const c=map.getCenter();$('coords').textContent=c.lat.toFixed(4)+'° N  '+c.lng.toFixed(4)+'° E';$('pitch').value=Math.round(map.getPitch());$('pitch-value').textContent=Math.round(map.getPitch())+'°';const is3d=map.getPitch()>5;['view3d','view2d'].forEach((id,i)=>{$(id).classList.toggle('active',i===0?is3d:!is3d);$(id).setAttribute('aria-pressed',String(i===0?is3d:!is3d))})});map.on('click','building-3d',e=>{const p=e.features[0].properties;const box=document.createElement('div');const h=document.createElement('strong');h.textContent=p['name:ko']||p.name||'건물 정보';const info=document.createElement('p');info.textContent='표시 높이 '+(p.render_height??6)+' m · 추정·기본값 포함';box.append(h,info);new maplibregl.Popup().setLngLat(e.lngLat).setDOMContent(box).addTo(map)});map.on('mouseenter','building-3d',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','building-3d',()=>map.getCanvas().style.cursor='');}catch(e){message('3D 지도를 시작하지 못했습니다. WebGL을 지원하는 브라우저에서 다시 열거나 인터넷 연결을 확인해 주세요.')}}
function applyTerrain(){if(!ready)return;const on=$('terrain').checked;Cartography.config.terrain.enabled=on;map.setTerrain(on?{source:'terrain-dem',exaggeration:Cartography.config.terrain.exaggeration}:null);map.setLayoutProperty('terrain-hillshade','visibility',on?'visible':'none')}
$('terrain').onchange=applyTerrain;
function applyLayers(){if(!ready)return;Cartography.config.buildings.enabled=$('buildings').checked;map.setLayoutProperty('building-3d','visibility',$('buildings').checked?'visible':'none');map.getStyle().layers.filter(l=>l.type==='symbol').forEach(l=>map.setLayoutProperty(l.id,'visibility',$('labels').checked?'visible':'none'))}
$('buildings').onchange=applyLayers;$('labels').onchange=applyLayers;$('pitch').oninput=()=>{if(map)map.setPitch(+$('pitch').value)};$('view3d').onclick=()=>map?.easeTo({pitch:60,duration:600});$('view2d').onclick=()=>map?.easeTo({pitch:0,bearing:0,duration:600});$('reset').onclick=()=>{if(!map)return;$('location').textContent='대한민국 전체';document.querySelectorAll('.place').forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});map.fitBounds([[124.5,33],[131.9,38.7]],{padding:45,pitch:0,bearing:0,duration:1500})};start();
